public static class WindowConstants
{
    public const double MaxWindowToMonitorRatio = 0.80;
    public const double MinContentWidthPixels = 500;
    public const double MinWindowHeightPixels = 500;

    public static Size GetScaledWindowMinimum(double scale, double titleBarHeightDip)
    {
        return new Size(
            MinContentWidthPixels / scale,
            (MinWindowHeightPixels - titleBarHeightDip) / scale);
    }
}

var monitorScale = foregroundWindowHandle.GetMonitorScale();
var minContentSize = WindowConstants.GetScaledWindowMinimum(monitorScale, TitleBarControl.ActualHeight);
MinWidth = minContentSize.Width;
MinHeight = minContentSize.Height + TitleBarControl.ActualHeight;
Size adjustedContentSize = scaledRequestedSize.Fit(monitorMaxContentSize, minContentSize);
